"""Exercise the real built site; fixtures are separately labeled browser-only HTML."""

import argparse
import hashlib
import importlib.metadata
import json
import threading
import urllib.parse
from functools import partial
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

from playwright.sync_api import sync_playwright


PAGES = [
    "5. Algorithms with Customized Client Training Loops",
    "10. Algorithms based on Neural Architecture Search and Model Search",
    "6. Client Selection Algorithms",
    "1. Server Aggregation Algorithms",
]
FIXTURE = r"""
<aside id="plato-browser-math-fixture" data-validation-fixture="synthetic">
<p>Browser validation inline probe: <span class="arithmatex">\(x^2+y^2\)</span>.</p>
<div class="arithmatex">\[\sum_{i=1}^{n} i = \frac{n(n+1)}{2}\]</div>
<div class="arithmatex">$$\int_0^1 x^2\,dx = \frac{1}{3}$$</div>
</aside>
"""
SNAPSHOT = r"""() => {
  const article = document.querySelector('.md-content__inner');
  const fixture = document.querySelector('#plato-browser-math-fixture');
  const original = [...article.querySelectorAll('.arithmatex')]
    .filter(node => !node.closest('#plato-browser-math-fixture'));
  const rendered = original.filter(node => node.querySelector('.katex'));
  const rects = rendered.map(node => {
    const rect = node.querySelector('.katex').getBoundingClientRect();
    return { width: rect.width, height: rect.height };
  });
  const fonts = [...document.fonts].filter(font => font.family.startsWith('KaTeX'));
  return {
    url: location.href, title: document.title,
    article_heading: article.querySelector('h1')?.textContent,
    identity: window.__platoDocumentIdentity,
    katex_version: window.katex?.version,
    renderer_type: typeof window.renderMathInElement,
    material_document_stream_type: typeof window.document$,
    original_math_nodes: original.length,
    original_rendered_math_nodes: rendered.length,
    original_unrendered: original.filter(node => !node.querySelector('.katex'))
      .map(node => node.textContent),
    original_mathml_nodes: rendered.filter(node => node.querySelector('math')).length,
    original_nonzero_rects: rects.filter(rect => rect.width > 0 && rect.height > 0).length,
    original_samples: rendered.slice(0, 3).map(node => ({
      tex: node.querySelector('annotation')?.textContent,
      text: node.textContent,
      html: node.outerHTML.slice(0, 1800)
    })),
    display_math_nodes: article.querySelectorAll('.katex-display').length,
    katex_error_nodes: article.querySelectorAll('.katex-error').length,
    fixture: fixture ? {
      math_nodes: fixture.querySelectorAll('.arithmatex').length,
      rendered_math_nodes: fixture.querySelectorAll('.katex').length,
      display_nodes: fixture.querySelectorAll('.katex-display').length,
      inline_nodes: [...fixture.querySelectorAll('.katex')]
        .filter(node => !node.closest('.katex-display')).length,
      display_styles: [...fixture.querySelectorAll('.katex-display')]
        .map(node => ({ display: getComputedStyle(node).display,
          width: node.getBoundingClientRect().width,
          height: node.getBoundingClientRect().height })),
      source_tex: [...fixture.querySelectorAll('annotation')].map(node => node.textContent)
    } : null,
    font_status: document.fonts.status,
    katex_fonts: fonts.map(font => ({ family: font.family, status: font.status })),
    source_script_urls: [...document.scripts].map(script => script.src).filter(Boolean),
    source_stylesheet_urls: [...document.querySelectorAll('link[rel=stylesheet]')]
      .map(link => link.href)
  };
}"""


class Handler(SimpleHTTPRequestHandler):
    def log_message(self, format, *args):
        pass


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--site", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--label", required=True)
    args = parser.parse_args()
    args.output.mkdir(parents=True, exist_ok=True)
    server = ThreadingHTTPServer(("127.0.0.1", 0), partial(Handler, directory=args.site))
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    transport = f"http://127.0.0.1:{server.server_port}/"
    base = "https://platodocs.netlify.app/"
    results = {
        "label": args.label, "site": str(args.site), "base_url": base,
        "local_transport": transport,
        "origin_mapping": "Browser requests to configured site_url are served by the owned local static server; original sitemap and HTML are preserved. CDN requests use their real URLs.",
        "playwright_version": importlib.metadata.version("playwright"),
        "fixture_html": FIXTURE, "checks": [], "events": [], "failures": [],
        "assets": [], "browser_tls_validation": "default; no ignore_https_errors",
    }
    paths = ["examples/algorithms/" + urllib.parse.quote(name) + "/" for name in PAGES]
    try:
        with sync_playwright() as playwright:
            executable = "/tmp/plato-remaining-docs-katex-browsers/chromium_headless_shell-1243/chrome-headless-shell-mac-arm64/chrome-headless-shell"
            browser = playwright.chromium.launch(headless=True, executable_path=executable)
            results["browser_version"] = browser.version
            results["browser_executable"] = executable
            for mode in ("untouched_page", "synthetic_display_fixture"):
                context = browser.new_context(viewport={"width": 1440, "height": 1080})
                context.add_init_script("window.__platoDocumentIdentity = crypto.randomUUID()")
                def serve_local(route):
                    response = route.fetch(url=transport + route.request.url.removeprefix(base))
                    if mode == "synthetic_display_fixture" and "text/html" in response.headers.get("content-type", ""):
                        body = response.text()
                        if "/examples/algorithms/" in route.request.url:
                            assert "</article>" in body
                            body = body.replace("</article>", FIXTURE + "</article>", 1)
                        route.fulfill(response=response, body=body)
                    else:
                        route.fulfill(response=response)
                context.route(base + "**", serve_local)
                page = context.new_page()
                expected_headers = {}
                expected_rendered = {}
                phase = {"mode": mode, "action": "setup"}
                page.on("console", lambda msg: results["events"].append({
                    **phase, "event": "console", "type": msg.type, "text": msg.text,
                    "location": msg.location,
                }))
                page.on("pageerror", lambda error: results["events"].append({
                    **phase, "event": "pageerror", "text": str(error),
                }))
                page.on("requestfailed", lambda req: results["events"].append({
                    **phase, "event": "requestfailed", "url": req.url,
                    "failure": req.failure, "resource_type": req.resource_type,
                }))
                page.on("request", lambda req: results["events"].append({
                    **phase, "event": "document_request", "url": req.url,
                    "resource_type": req.resource_type,
                    "navigation_request": req.is_navigation_request(),
                }) if req.url.startswith(base) and req.resource_type in ("document", "fetch", "xhr") else None)

                def capture_response(response):
                    if "unpkg.com/katex@" in response.url and response.url.endswith((".js", ".css")):
                        try:
                            body = response.body()
                            results["assets"].append({
                                **phase, "url": response.url, "status": response.status,
                                "content_type": response.headers.get("content-type"),
                                "sha256": hashlib.sha256(body).hexdigest(), "bytes": len(body),
                            })
                        except Exception as error:
                            results["events"].append({**phase, "event": "asset_capture_error", "text": str(error)})
                page.on("response", capture_response)

                def collect(action, name, prior_identity=None):
                    if action == "instant":
                        # The URL changes before the fetched content is injected.
                        # Wait for the actual target article and production rendering.
                        page.wait_for_function("expected => document.querySelector('.md-content__inner h1')?.textContent === expected", arg=expected_headers[name])
                        page.wait_for_function("expected => [...document.querySelectorAll('.md-content__inner .arithmatex')].filter(node => !node.closest('#plato-browser-math-fixture') && node.querySelector('.katex')).length === expected", arg=expected_rendered[name])
                        if mode == "synthetic_display_fixture":
                            page.wait_for_selector("#plato-browser-math-fixture .katex-display")
                    page.wait_for_load_state("networkidle")
                    page.evaluate("async () => { await document.fonts.ready; }")
                    # No manual renderer call: production document$ subscriber owns rendering.
                    row = {"mode": mode, "action": action, "page": name, **page.evaluate(SNAPSHOT)}
                    if action == "direct":
                        expected_headers[name] = row["article_heading"]
                        expected_rendered[name] = row["original_rendered_math_nodes"]
                    if prior_identity is not None:
                        row["same_document_identity"] = row["identity"] == prior_identity
                    screenshot = args.output / f"{mode}-{action}-{name.split('.')[0]}.png"
                    if mode == "synthetic_display_fixture":
                        page.locator("#plato-browser-math-fixture").screenshot(path=screenshot)
                    elif name == PAGES[0]:
                        page.locator(".arithmatex").first.scroll_into_view_if_needed()
                        page.screenshot(path=screenshot)
                    if screenshot.exists():
                        row["screenshot"] = str(screenshot)
                        row["screenshot_sha256"] = hashlib.sha256(screenshot.read_bytes()).hexdigest()
                    results["checks"].append(row)
                    failures = []
                    if row["original_math_nodes"] == 0:
                        failures.append("no original arithmatex nodes")
                    if row["original_rendered_math_nodes"] != row["original_math_nodes"]:
                        failures.append("original math not fully rendered")
                    if row["original_nonzero_rects"] != row["original_math_nodes"]:
                        failures.append("original math has zero-sized boxes")
                    if row["original_mathml_nodes"] != row["original_math_nodes"]:
                        failures.append("missing MathML output")
                    if row["katex_error_nodes"]:
                        failures.append("KaTeX error nodes")
                    if row["katex_version"] != "0.19.0" or row["renderer_type"] != "function":
                        failures.append("unexpected KaTeX version or missing renderer")
                    if prior_identity is not None and not row["same_document_identity"]:
                        failures.append("Material click performed a full document reload")
                    if mode == "synthetic_display_fixture":
                        fixture = row["fixture"]
                        if not fixture or fixture["rendered_math_nodes"] != 3 or fixture["display_nodes"] != 2 or fixture["inline_nodes"] != 1:
                            failures.append("synthetic inline/display probes not fully rendered")
                        elif any(style["display"] != "block" or style["width"] <= 0 or style["height"] <= 0 for style in fixture["display_styles"]):
                            failures.append("synthetic display probe layout failed")
                    if failures:
                        results["failures"].append({"mode": mode, "action": action, "page": name, "failures": failures})

                for name, path in zip(PAGES, paths):
                    phase["action"] = "direct-load-" + name.split(".")[0]
                    response = page.goto(base + path, wait_until="networkidle")
                    assert response.status == 200
                    collect("direct", name)
                phase["action"] = "instant-start-home"
                page.goto(base, wait_until="networkidle")
                identity = page.evaluate("window.__platoDocumentIdentity")
                for name, path in zip(PAGES, paths):
                    phase["action"] = "instant-click-" + name.split(".")[0]
                    links = page.locator("a.md-nav__link")
                    target = None
                    for index in range(links.count()):
                        candidate = links.nth(index)
                        if candidate.evaluate("a => a.href") == base + path:
                            target = candidate
                            break
                    assert target is not None, name
                    toggles = target.evaluate("""a => {
                      const toggles = [];
                      for (let li = a.closest('li'); li; li = li.parentElement.closest('li')) {
                        const input = li.querySelector(':scope > input.md-nav__toggle');
                        if (input && !input.checked) toggles.push(input.id);
                      }
                      return toggles.reverse();
                    }""")
                    for toggle in toggles:
                        page.locator(f'label[for="{toggle}"]').first.click()
                    # Real visible click on the built site's existing navigation link.
                    # Material may serve a prior page from its own in-memory cache.
                    target.click()
                    page.wait_for_url(base + path)
                    collect("instant", name, identity)
                context.close()
            browser.close()
    except Exception as error:
        results["failures"].append({"exception": repr(error)})
    finally:
        server.shutdown()
        server.server_close()
    console_failures = [event for event in results["events"] if event["event"] == "pageerror" or (event["event"] == "console" and event["type"] == "error")]
    results["console_errors"] = console_failures
    if console_failures:
        results["failures"].append({"browser_console_errors": len(console_failures)})
    results["status"] = "PASS" if not results["failures"] else "FAIL"
    (args.output / "browser-results.json").write_text(json.dumps(results, indent=2) + "\n")
    print(json.dumps({"label": args.label, "status": results["status"], "checks": len(results["checks"]), "failures": results["failures"]}, indent=2))
    raise SystemExit(bool(results["failures"]))


if __name__ == "__main__":
    main()
